import {learningLevel} from './core.js?v=10';
import {planSearch,matchConcepts,fromOpenAlex,samePaper,searchUrl,isEnglishRecord,translateQuery,learningSearchUrls,selectLearningPapers} from './discovery-core.js?v=10';
export function setupDiscovery({getPapers,addPaper,pickPaper,createGraph}){
 const $=s=>document.querySelector(s),dialog=$('#discoverDialog');let mode='area',controller=null,requestId=0,results=[],nextCursor=null,total=0,activeQuery='',activeConcepts=[],building=false,buildId=0,preparedEnglish=false,queryEdited=false,learning=false;
 const el=(tag,attrs={},text)=>{const n=document.createElement(tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);if(text!==undefined)n.textContent=text;return n};
 function strip(s){return new DOMParser().parseFromString(String(s||''),'text/html').body.textContent||''}
 function status(text){$('#discoverStatus').textContent=text}
 function proposal(){preparedEnglish=$('#discoverInputLanguage').value==='en';queryEdited=false;const plan=planSearch($('#discoverInput').value,mode,$('#discoverBreadth').value==='strict');$('#discoverQuery').value=preparedEnglish?plan.query:$('#discoverInput').value.trim();$('#discoverConcepts').replaceChildren(...plan.concepts.map(c=>el('span',{},c.label)));return plan}
 function setMode(value){mode=value;$('#modeArea').setAttribute('aria-pressed',String(mode==='area'));$('#modeExperiment').setAttribute('aria-pressed',String(mode==='experiment'));$('#discoverPrompt').textContent=mode==='area'?'¿Qué área quieres explorar?':'Describe tu proyecto o investigación';$('#discoverInput').placeholder=mode==='area'?'Por ejemplo: bases de programación, historia medieval o energía solar':'Por ejemplo: quiero comparar dos métodos de enseñanza de programación y evaluar cómo influyen en el aprendizaje.';proposal()}
 function cancel(){const active=!!controller||building;buildId++;building=false;if(controller){controller.abort();controller=null;requestId++}$('#discoverGraphCount').disabled=false;$('#discoverCreateGraph').disabled=false;$('#discoverSearch').disabled=false;$('#discoverCancel').hidden=true;if(active)status('Búsqueda cancelada.')}
 function close(){cancel();dialog.close()}
 $('#discoverOpen').onclick=()=>{dialog.showModal();$('#discoverInput').focus();render()};$('#discoverClose').onclick=close;dialog.addEventListener('cancel',cancel);dialog.addEventListener('pointerdown',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom){e.preventDefault();close()}});$('#discoverCancel').onclick=cancel;
 $('#modeArea').onclick=()=>setMode('area');$('#modeExperiment').onclick=()=>setMode('experiment');$('#discoverInput').oninput=proposal;$('#discoverBreadth').onchange=proposal;$('#discoverInputLanguage').onchange=proposal;$('#discoverQuery').oninput=()=>{queryEdited=true};
 $('#discoverLearning').onclick=()=>{learning=!learning;$('#discoverLearning').setAttribute('aria-pressed',String(learning));$('#discoverLearning').textContent=learning?'Aprender desde cero ✓':'Aprender desde cero ○';render()};
 function existing(p){return getPapers().find(known=>samePaper(known,p))}
 function rankedResults(){return results.map((p,index)=>({p,index,matches:matchConcepts(p,activeConcepts)})).sort((a,b)=>b.matches.length-a.matches.length||a.index-b.index)}
 function render(){const list=$('#discoverResults');list.replaceChildren();const ranked=rankedResults();$('#discoverGraphTools').hidden=!results.length;$('#discoverCreateGraph').disabled=!!controller||building;$('#discoverLearning').disabled=!!controller||building;
 for(const {p,matches}of ranked){const article=el('article',{class:'discovery-result'});if(learning)article.append(el('span',{class:'learning-label'},learningLevel(p).label));article.append(el('h3',{},p.title));const meta=el('div',{class:'result-meta'});if(p.preprint)meta.append(el('span',{class:'preprint'},'PREPRINT'));const authors=p.authors.split(' and ');meta.append(el('span',{},[authors.slice(0,3).join('; ')+(authors.length>3?' et al.':''),p.journal,p.year].filter(Boolean).join(' · ')));article.append(meta);article.append(el('p',{class:'result-relevance'},matches.length?'Coincidencias en título o abstract: '+matches.map(c=>c.label).join(' · '):'Recuperado por OpenAlex. Revisa el abstract para valorar su utilidad.'));
 if(p.abstract){const details=el('details');details.append(el('summary',{},'Ver abstract'),el('p',{},p.abstract));article.append(details)}else article.append(el('p',{class:'result-meta'},'Sin abstract disponible.'));
 const actions=el('div',{class:'result-actions'}),known=existing(p),add=el('button',{},known?'Ya en tu biblioteca ✓':'Añadir al grafo ＋');add.disabled=!!known;add.onclick=()=>{addPaper(p);render()};actions.append(add);if(known){const view=el('button',{},'Ver en el grafo');view.onclick=()=>{close();pickPaper(known.id)};actions.append(view)}actions.append(el('a',{href:p.url,target:'_blank',rel:'noopener noreferrer'},'OpenAlex ↗'));article.append(actions);list.append(article)}
 $('#discoverMore').hidden=!nextCursor||results.length>=total;$('#discoverMore').disabled=!!controller||building;
 }
 async function search(more=false){if(controller||(!more&&building))return false;if(!more){activeQuery=$('#discoverQuery').value.trim()||proposal().query;if(!activeQuery){status('Escribe un área o describe tu experimento.');$('#discoverInput').focus();return}activeConcepts=planSearch($('#discoverInput').value,mode,$('#discoverBreadth').value==='strict').concepts;results=[];nextCursor=null;total=0;render()}
 const requestedCursor=more?nextCursor:'*';if(!requestedCursor)return;const id=++requestId,abort=new AbortController();controller=abort;$('#discoverSearch').disabled=true;$('#discoverCancel').hidden=false;$('#discoverMore').disabled=true;status(more?'Buscando más resultados…':'Buscando en OpenAlex…');const timer=setTimeout(()=>abort.abort(),60000);
 try{if(!more&&!preparedEnglish){status('Preparando la consulta en inglés…');const translated=await translateQuery(queryEdited?activeQuery:$('#discoverInput').value,{signal:abort.signal,area:mode==='area'});if(id!==requestId)return false;activeQuery=planSearch(strip(translated),mode,$('#discoverBreadth').value==='strict').query;preparedEnglish=true;$('#discoverQuery').value=activeQuery}activeConcepts=planSearch(activeQuery,mode,$('#discoverBreadth').value==='strict').concepts;$('#discoverConcepts').replaceChildren(...activeConcepts.map(c=>el('span',{},c.label)));status(more?'Buscando más resultados…':'Buscando en OpenAlex…');const response=await fetch(searchUrl(activeQuery,requestedCursor),{signal:abort.signal,credentials:'omit',referrerPolicy:'no-referrer'});if(!response.ok)throw Error(response.status===429?'El servicio está ocupado. Espera unos segundos y vuelve a intentarlo.':'OpenAlex no está disponible ahora. Inténtalo de nuevo.');const data=await response.json();if(id!==requestId)return;const records=data.results||[],batch=records.filter(isEnglishRecord).map(r=>fromOpenAlex(r,strip)).filter(Boolean);for(const paper of batch)if(!results.some(p=>samePaper(p,paper)))results.push(paper);total=Number(data.meta?.count)||0;const page=Number(data.meta?.page||(requestedCursor==='*'?1:requestedCursor));nextCursor=records.length&&page*20<total?String(page+1):null;
 status(results.length?`${results.length} resultados cargados de ${total.toLocaleString('es-ES')}. Solo inglés. Coincidencias en títulos y abstracts.`:'No hay resultados. Prueba términos más amplios o cambia a «Relacionada con algún concepto».');return true;
 }catch(error){if(id===requestId)status(error.name==='AbortError'?'La consulta tardó demasiado. Vuelve a intentarlo.':error.message||'No se pudo conectar con OpenAlex.');return false}finally{clearTimeout(timer);if(id===requestId){controller=null;$('#discoverSearch').disabled=building;$('#discoverCancel').hidden=!building;render()}}}
 async function learningCandidates(count){const id=++requestId,abort=new AbortController();controller=abort;const timer=setTimeout(()=>abort.abort(),60000);try{for(const [index,base]of learningSearchUrls(activeQuery).entries()){if(index===1&&count===1)break;const desired=index===0?Math.ceil(count*.4):Math.max(1,Math.floor(count*.25));for(let page=1;page<=Math.min(4,Math.max(2,Math.ceil(count/20)));page++){const u=new URL(base);u.searchParams.set('page',String(page));status(index===0?'Buscando fundamentos e introducciones…':'Buscando aplicaciones y profundización…');const response=await fetch(u.href,{signal:abort.signal,credentials:'omit',referrerPolicy:'no-referrer'});if(!response.ok)throw Error('No se pudo completar la búsqueda de aprendizaje. Inténtalo de nuevo.');const data=await response.json();if(id!==requestId)return false;const records=data.results||[];for(const p of records.filter(isEnglishRecord).map(r=>fromOpenAlex(r,strip)).filter(Boolean))if(!results.some(x=>samePaper(x,p)))results.push(p);const level=index===0?0:3;if(results.filter(p=>learningLevel(p).level===level).length>=desired||!records.length||page*20>=Number(data.meta?.count||0))break}}return true}catch(error){if(id===requestId)status(error.name==='AbortError'?'La búsqueda de aprendizaje tardó demasiado. Inténtalo de nuevo.':error.message);return false}finally{clearTimeout(timer);if(id===requestId)controller=null}}
 $('#discoverCreateGraph').onclick=async()=>{if(controller||building)return;const count=Number($('#discoverGraphCount').value);if(!Number.isInteger(count)||count<1||count>200){status('Elige un número entero de artículos entre 1 y 200.');$('#discoverGraphCount').focus();return}if(!results.length){status('Busca artículos antes de crear el grafo.');return}const current=++buildId;building=true;$('#discoverGraphCount').disabled=true;$('#discoverSearch').disabled=true;$('#discoverCancel').hidden=false;render();
 try{if(learning){const ok=await learningCandidates(count);if(current!==buildId||!ok)return}while(results.length<count&&nextCursor){const ok=await search(true);if(current!==buildId||!ok)return}if(current!==buildId)return;if(results.length<count){status(`Solo hay ${results.length} artículos únicos en inglés disponibles para esta consulta. Elige una cantidad menor o amplía la búsqueda.`);return}const choice=learning?selectLearningPapers(rankedResults().map(item=>item.p),count):{papers:rankedResults().slice(0,count).map(item=>item.p)};if(choice.missingBasics){status('No se han encontrado materiales claramente introductorios. Prueba una consulta más general o desactiva «Aprender desde cero».');return}createGraph(choice.papers,{learning});building=false;close()}finally{if(current===buildId){building=false;$('#discoverGraphCount').disabled=false;$('#discoverSearch').disabled=false;$('#discoverCancel').hidden=true;render()}}};
 $('#discoverSearch').onclick=()=>search(false);$('#discoverMore').onclick=()=>search(true);
 return {cancel};
}
